import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentTimetable({ user }) {
  const [timetable, setTimetable] = useState([]);
  const studentGrade = user?.grade || "Grade 8";

  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const timeSlots = ['08:00 AM', '10:30 AM', '01:00 PM', '03:30 PM'];

  useEffect(() => {
    const targetGradeNum = String(studentGrade).replace(/\D/g, '');

    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        const data = res.data || [];
        const filtered = data.filter(t => (t.grade || '').replace(/\D/g, '') === targetGradeNum);
        setTimetable(filtered);
      }).catch(() => setTimetable([]));
  }, [studentGrade]);

  return (
    <div style={styles.whiteBox}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '18px' }}>
        <h3 style={{ margin: 0, fontSize: '18px', color: '#1e293b', fontWeight: 'bold' }}>
          🗓️ Live Weekly Class Timetable ({studentGrade})
        </h3>
      </div>

      {timetable.length > 0 ? (
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '13.5px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={{ padding: '12px', textAlign: 'left', color: '#64748b' }}>Time Slot</th>
              {daysOfWeek.map(day => <th key={day} style={{ padding: '12px', color: '#64748b' }}>{day}</th>)}
            </tr>
          </thead>
          <tbody>
            {timeSlots.map(slot => (
              <tr key={slot} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{ padding: '14px 10px', fontWeight: 'bold', textAlign: 'left', color: '#334155' }}>{slot}</td>
                {daysOfWeek.map(day => {
                  const match = timetable.find(t => (t.day || '').toLowerCase().startsWith(day.toLowerCase()) && (t.time_slot || '').replace(/\s/g, '').toLowerCase() === slot.replace(/\s/g, '').toLowerCase());
                  return (
                    <td key={day} style={{ padding: '6px' }}>
                      {match ? (
                        <div style={styles.classBadge}>
                          <div style={{ fontWeight: 'bold' }}>{match.subject}</div>
                          <div style={{ fontSize: '11px', color: '#15803d' }}>👨‍🏫 {match.teacher}</div>
                        </div>
                      ) : <span style={{ color: '#cbd5e1' }}>-</span>}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div style={{ textAlign: 'center', padding: '50px 20px', backgroundColor: '#f8fafc', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
          <div style={{ fontSize: '40px', marginBottom: '10px' }}>📅</div>
          <h4 style={{ margin: '0 0 6px 0', fontSize: '16px', color: '#1e293b' }}>No Timetable Scheduled Yet</h4>
          <p style={{ margin: 0, fontSize: '13px', color: '#64748b' }}>
            Weekly class schedule for <b>{studentGrade}</b> will be published here by the administration soon.
          </p>
        </div>
      )}
    </div>
  );
}

const styles = {
  whiteBox: { 
    backgroundColor: '#fff', 
    padding: '24px', 
    borderRadius: '18px', 
    border: '1px solid #e2e8f0', 
    boxShadow: '0 4px 14px rgba(0,0,0,0.03)' 
  },
  classBadge: { 
    backgroundColor: '#f0fdf4', 
    border: '1px solid #bbf7d0', 
    borderRadius: '8px', 
    padding: '6px', 
    fontSize: '11.5px', 
    color: '#145c2e' 
  }
};
